import json, subprocess, sys, base64, urllib.request, urllib.parse, time
out = sys.argv[1]
ctx = 'gke_tsdtechnology_us-central1-c_tsd'
dep = json.loads(subprocess.check_output(['kubectl','--context',ctx,'get','deploy','tsdws-prod','-o','json']))
env = {e['name']: e.get('value') for e in dep['spec']['template']['spec']['containers'][0]['env']}
auth = base64.b64encode(f"{env['LANGFUSE_PUBLIC_KEY']}:{env['LANGFUSE_SECRET_KEY']}".encode()).decode()
host = env['LANGFUSE_HOST'].rstrip('/')
start = '2026-11-13T03:00:00Z'
end = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
cursor, n, pages = None, 0, 0
with open(out, 'w') as f:
    while True:
        p = {'fromStartTime': start, 'toStartTime': end, 'type': 'GENERATION', 'limit': 1000,
             'fields': 'core,basic,usage,metadata,model'}
        if cursor: p['cursor'] = cursor
        req = urllib.request.Request(f'{host}/api/public/v2/observations?' + urllib.parse.urlencode(p),
                                     headers={'Authorization': 'Basic ' + auth})
        for attempt in range(6):
            try:
                body = json.load(urllib.request.urlopen(req, timeout=120)); break
            except Exception as e:
                print('retry', pages, e, file=sys.stderr); time.sleep(3 * (attempt + 1))
        else:
            raise SystemExit('failed')
        for o in body['data']: f.write(json.dumps(o) + '\n')
        n += len(body['data']); pages += 1
        cursor = (body.get('meta') or {}).get('cursor')
        print('page', pages, 'rows', n, 'cursor', bool(cursor), file=sys.stderr)
        if not cursor or not body['data']: break
print('done', n, 'to', end)

