import gzip,json,os,base64,struct,collections as C
def dims(b64):
    h=base64.b64decode(b64[:4000]+'='*(-len(b64[:4000])%4))
    if h[:8]==b'\x89PNG\r\n\x1a\n': return struct.unpack('>II',h[16:24])
    if h[:2]==b'\xff\xd8':
        i=2
        while i<len(h)-9:
            if h[i]!=0xFF: i+=1; continue
            m=h[i+1]
            if m in (0xC0,0xC1,0xC2): hh,ww=struct.unpack('>HH',h[i+5:i+9]); return ww,hh
            i+=2+struct.unpack('>H',h[i+2:i+4])[0]
    return None
def imgtok(src):
    d=dims(src.get('data','')) if src.get('type')=='base64' else None
    if not d: return 1600
